class OrderDetailPage extends ConsumerStatefulWidget {
  final String orderId;
  final String? checkoutResult;
  const OrderDetailPage({super.key, required this.orderId, this.checkoutResult});
  @override ConsumerState<OrderDetailPage> createState() => _OrderDetailPageState();
}

class _OrderDetailPageState extends ConsumerState<OrderDetailPage> {
  Timer? fallback;
  int refreshes = 0;
  @override void initState() { super.initState(); if (widget.checkoutResult == 'success') fallback = Timer.periodic(const Duration(seconds: 5), (timer) { if (++refreshes > 12) { timer.cancel(); return; } ref.invalidate(orderDetailProvider(widget.orderId)); }); }
  @override void dispose() { fallback?.cancel(); super.dispose(); }
  @override Widget build(BuildContext context) => ref.watch(orderDetailProvider(widget.orderId)).when(loading: () => const PageColumns(center: Padding(padding: EdgeInsets.all(AppSpacing.lg), child: HBSkeleton(height: 600))), error: (_, __) => PageColumns(center: HBCard(child: HBEmptyState(icon: Icons.receipt_long_outlined, title: 'orders.unavailable_title'.tr(), message: 'orders.unavailable_message'.tr()))), data: (detail) { if (detail.order.status == OrderStatus.paid) fallback?.cancel(); return OrderDetailBody(detail: detail, confirmingCheckout: widget.checkoutResult == 'success' && detail.order.status == OrderStatus.pendingPayment); });
}

class OrderDetailBody extends ConsumerWidget {
  final OrderDetail detail;
  final bool confirmingCheckout;
  const OrderDetailBody({super.key, required this.detail, required this.confirmingCheckout});
  Future<void> ship(BuildContext context, WidgetRef ref) async { final result = await showModalBottomSheet<ShippingValue>(context: context, isScrollControlled: true, useSafeArea: true, builder: (_) => ShippingSheet(shipping: detail.order.deliveryMethod == 'shipping')); if (result == null || !context.mounted) return; try { await ref.read(ordersRepositoryProvider).markShipped(detail.order.id, carrier: result.carrier, trackingCode: result.tracking); ref.invalidate(orderDetailProvider(detail.order.id)); ref.invalidate(ordersProvider); } on AppException catch (error) { if (context.mounted) _error(context, error); } }
  Future<void> confirm(BuildContext context, WidgetRef ref) async { final accepted = await showDialog<bool>(context: context, builder: (dialog) => AlertDialog(title: Text('orders.confirm_received_title'.tr()), content: Text('orders.confirm_received_message'.tr()), actions: [HBButton.ghost(label: 'common.cancel'.tr(), onPressed: () => dialog.pop(false)), HBButton.primary(label: 'orders.confirm_received'.tr(), onPressed: () => dialog.pop(true))])) ?? false; if (!accepted || !context.mounted) return; try { await ref.read(ordersRepositoryProvider).confirmReceived(detail.order.id); ref.invalidate(orderDetailProvider(detail.order.id)); ref.invalidate(ordersProvider); } on AppException catch (error) { if (context.mounted) _error(context, error); } }
  Future<void> action(BuildContext context, WidgetRef ref, OrderRefundAction action) async {
    final value = await showModalBottomSheet<OrderRefundValue>(context: context, isScrollControlled: true, useSafeArea: true, builder: (_) => OrderRefundSheet(action: action));
    if (value == null || !context.mounted) return;
    try {
      final repository = ref.read(ordersRepositoryProvider);
      OrderActionResult? result;
      if (action == OrderRefundAction.cancelBuyer || action == OrderRefundAction.cancelSeller) result = await repository.cancel(detail.order.id, reason: value.note);
      if (action == OrderRefundAction.request) await repository.requestRefund(detail.order.id, value.note!);
      if (action == OrderRefundAction.approve) result = await repository.decideRefund(detail.order.id, approve: true, note: value.note);
      if (action == OrderRefundAction.decline) result = await repository.decideRefund(detail.order.id, approve: false, note: value.note);
      if (result?.needsStripeRefund == true) await ref.read(paymentsRepositoryProvider).refund(detail.order.id);
      ref.invalidate(orderDetailProvider(detail.order.id)); ref.invalidate(ordersProvider);
    } on AppException catch (error) { if (context.mounted) _error(context, error); }
  }
  @override Widget build(BuildContext context, WidgetRef ref) { final order = detail.order; final refundRequests = detail.events.where((event) => event.kind == 'refund_requested').toList(); final refundRequest = refundRequests.isEmpty ? null : refundRequests.last; return PageColumns(center: CustomScrollView(slivers: [SliverPadding(padding: const EdgeInsets.symmetric(vertical: AppSpacing.lg), sliver: SliverList.list(children: [if (confirmingCheckout) ...[HBTile(child: Row(children: [const SizedBox.square(dimension: 20, child: CircularProgressIndicator(strokeWidth: 2)), const SizedBox(width: AppSpacing.sm), Expanded(child: Text('orders.confirming_payment'.tr()))])), const SizedBox(height: AppSpacing.md)], OrderStatusHeader(detail: detail), const SizedBox(height: AppSpacing.md), OrderArticleCard(order: order), if (detail.ticketCode != null) ...[const SizedBox(height: AppSpacing.md), OrderTicketCard(code: detail.ticketCode!)], const SizedBox(height: AppSpacing.md), OrderAmountsCard(detail: detail), if (order.kind != 'event_ticket') ...[const SizedBox(height: AppSpacing.md), OrderDeliveryCard(detail: detail)], const SizedBox(height: AppSpacing.md), OrderCounterpartCard(detail: detail), if (order.status == OrderStatus.refundRequested && detail.isSeller) ...[const SizedBox(height: AppSpacing.md), RefundRequestCard(reason: refundRequest?.data['reason']?.toString(), onApprove: () => action(context, ref, OrderRefundAction.approve), onDecline: () => action(context, ref, OrderRefundAction.decline))], const SizedBox(height: AppSpacing.md), OrderTimeline(events: detail.events), if (detail.isSeller && order.canShip) ...[const SizedBox(height: AppSpacing.md), SizedBox(width: double.infinity, child: HBButton.primary(label: order.deliveryMethod == 'shipping' ? 'orders.mark_shipped'.tr() : 'orders.mark_delivered'.tr(), onPressed: () => ship(context, ref)))], if (detail.isBuyer && order.canConfirm) ...[const SizedBox(height: AppSpacing.md), SizedBox(width: double.infinity, child: HBButton.primary(label: 'orders.confirm_received'.tr(), onPressed: () => confirm(context, ref)))], if (detail.isBuyer && order.status == OrderStatus.pendingPayment) ...[const SizedBox(height: AppSpacing.sm), HBButton.ghost(label: 'p34b.cancel_action'.tr(), onPressed: () => action(context, ref, OrderRefundAction.cancelBuyer))], if (detail.isBuyer && const {OrderStatus.paid, OrderStatus.shipped}.contains(order.status)) ...[const SizedBox(height: AppSpacing.sm), HBButton.secondary(label: 'p34b.request_refund'.tr(), onPressed: () => action(context, ref, OrderRefundAction.request))], if (detail.isSeller && order.status == OrderStatus.paid) ...[const SizedBox(height: AppSpacing.sm), HBButton.secondary(label: 'p34b.cancel_refund'.tr(), onPressed: () => action(context, ref, OrderRefundAction.cancelSeller))], if (order.status == OrderStatus.completed && order.canReview && order.listingId != null) ...[const SizedBox(height: AppSpacing.md), HBCard(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('orders.review_title'.tr(), style: context.textStyles.titleMedium), const SizedBox(height: AppSpacing.sm), HBButton.secondary(label: 'orders.review_action'.tr(), onPressed: () => context.push(AppRoutes.marketplaceDetailPath(order.listingId!))) ]))], const SizedBox(height: AppSpacing.xl)]))])); }
}

