async { try { final uri = await ref.read(paymentsRepositoryProvider).connectLogin(); await launchUrl(uri, mode: LaunchMode.externalApplication); } on AppException catch (error) { if (context.mounted) _error(context, error); } }), if (order.trackingCode != null) HBButton.ghost(label: 'orders.copy_tracking'.tr(), icon: Icons.copy_outlined, onPressed: () => Clipboard.setData(ClipboardData(text: order.trackingCode!))), if (order.status == OrderStatus.pendingPayment && order.checkoutUrl != null) HBButton.primary(label: 'orders.resume_payment'.tr(), onPressed: () => launchUrl(Uri.parse(order.checkoutUrl!))) ])); } }

